import {Platform, View} from 'react-native';
import type * as ReanimatedNS from 'react-native-reanimated';
import type ReanimatedCarouselDefault from 'react-native-reanimated-carousel';

interface ReanimatedRuntime {
  View: typeof View;
  FadeInRight: typeof ReanimatedNS.FadeInRight;
  FadeInUp: typeof ReanimatedNS.FadeInUp;
  FadeOutDown: typeof ReanimatedNS.FadeOutDown;
}

interface ReanimatedRequireModule {
  default?: {View: typeof View};
  View?: typeof View;
  FadeInRight: typeof ReanimatedNS.FadeInRight;
  FadeInUp: typeof ReanimatedNS.FadeInUp;
  FadeOutDown: typeof ReanimatedNS.FadeOutDown;
}

/**
 * iOS Debug Hermes SIGSEGVs when react-native-reanimated installs its
 * RuntimeDecorator (instanceof / getPrototypeOf). Skip the native module
 * only on that runtime. iOS Release and Android keep the production path.
 */
export const shouldLoadReanimatedNative = !(
  Platform.OS === 'ios' && __DEV__
);

export const loadReanimatedModule = (): ReanimatedRuntime | null => {
  if (!shouldLoadReanimatedNative) {
    return null;
  }
  const mod = require('react-native-reanimated') as ReanimatedRequireModule;
  const animatedView = mod.default?.View ?? mod.View;
  if (!animatedView) {
    return null;
  }
  return {
    View: animatedView,
    FadeInRight: mod.FadeInRight,
    FadeInUp: mod.FadeInUp,
    FadeOutDown: mod.FadeOutDown,
  };
};

export const loadReanimatedCarousel = ():
  | typeof ReanimatedCarouselDefault
  | null => {
  if (!shouldLoadReanimatedNative) {
    return null;
  }
  const mod = require('react-native-reanimated-carousel') as {
    default?: typeof ReanimatedCarouselDefault;
  } & typeof ReanimatedCarouselDefault;
  return (mod.default ?? mod) as typeof ReanimatedCarouselDefault;
};

