if (configFile.error) {
  console.error(ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, cwd);
const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: parsed.options,
});

const changed = [
  'src/navigation/main-tab/main-tab-navigator.tsx',
  'src/screens/MeasureScreen/MeasureScreen.tsx',
  'src/screens/doctor-detail-screen/doctor-detail-screen.styles.ts',
  'src/screens/doctor-detail-screen/doctor-detail-screen.tsx',
  'src/screens/home/home-screen/home-screen.tsx',
  'src/screens/my-plans-screen/my-plans-screen.tsx',
  'src/screens/shopping-cart-screen/shopping-cart-screen.styles.ts',
  'src/utils/reanimated-native.ts',
].map((p) => path.normalize(path.join(cwd, p)));
const changedSet = new Set(changed.map((p) => p.toLowerCase()));

function fileOf(d) {
  return d.file ? path.normalize(d.file.fileName) : null;
}

function fmt(d) {
  const file = fileOf(d);
  let loc = '';
  if (d.file && typeof d.start === 'number') {
    const pos = d.file.getLineAndCharacterOfPosition(d.start);
    loc = `${path.relative(cwd, file)}:${pos.line + 1}:${pos.character + 1}`;
  }
  return `${d.category}/${d.code} ${loc} ${ts.flattenDiagnosticMessageText(d.messageText, '\n')}`;
}

const hit = [...program.getSyntacticDiagnostics(), ...program.getSemanticDiagnostics()]
  .filter((d) => {
    const f = fileOf(d);
    return f && changedSet.has(f.toLowerCase());
  });
console.log('=== semantic/syntactic for changed files ===');
console.log(hit.length ? hit.map(fmt).join('\n') : 'NONE');

const ls = ts.createLanguageService({
  getCompilationSettings: () => parsed.options,
  getScriptFileNames: () => parsed.fileNames,
  getScriptVersion: () => '0',
  getScriptSnapshot: (fileName) => {
    if (!fs.existsSync(fileName)) return undefined;
    return ts.ScriptSnapshot.fromString(fs.readFileSync(fileName, 'utf8'));
  },
  getCurrentDirectory: () => cwd,
  getDefaultLibFileName: (opts) => ts.getDefaultLibFilePath(opts),
  fileExists: ts.sys.fileExists,
  readFile: ts.sys.readFile,
  readDirectory: ts.sys.readDirectory,
  directoryExists: ts.sys.directoryExists,
  getDirectories: ts.sys.getDirectories,
}, ts.createDocumentRegistry());

console.log('=== suggestion diagnostics ===');
for (const abs of changed) {
  if (!fs.existsSync(abs)) {
    console.log('MISSING', abs);
    continue;
  }
  const sf = program.getSourceFile(abs);
  if (!sf) {
    console.log('NOT IN PROGRAM', path.relative(cwd, abs));
    continue;
  }
  const merged = [...program.getSuggestionDiagnostics(sf), ...ls.getSuggestionDiagnostics(abs)];
  const seen = new Set();
  const uniq = [];
  for (const d of merged) {
    const key = fmt(d);
    if (seen.has(key)) continue;
    seen.add(key);
    uniq.push(d);
  }
  if (uniq.length) {
    console.log('---', path.relative(cwd, abs));
    for (const d of uniq) console.log(fmt(d));
  }
}
console.log('=== suggestion scan done ===');

