() => {
  const frames = Array.from(document.querySelectorAll('iframe'));
  const out = frames.map((f, i) => {
    let inner = null;
    try {
      const doc = f.contentDocument;
      inner = doc ? {
        title: doc.title,
        buttons: Array.from(doc.querySelectorAll('button, [role=button], input[type=submit]')).map(el => ({text: (el.innerText||el.value||'').trim(), id: el.id, type: el.tagName})),
        inputs: Array.from(doc.querySelectorAll('input')).map(el => ({type: el.type, value: el.value ? 'HAS_VALUE' : '', name: el.name}))
      } : 'no-doc';
    } catch (e) {
      inner = 'cross-origin: ' + e.message;
    }
    return {i, src: f.src, title: f.title, inner};
  });
  return {url: location.href, frames: out, buttons: Array.from(document.querySelectorAll('button')).map(b => b.innerText)};
}

